<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\{User,Role}; use App\Services\CredentialService; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class StudentController extends Controller {
 public function index(Request $r){$q=DB::table('students as s')->leftJoin('study_groups as g','g.id','=','s.current_group_id')->select('s.*','g.name as group_name');if($r->group)$q->where('g.id',$r->group);if($r->status)$q->where('s.status',$r->status);if($r->q){$x='%'.$r->q.'%';$q->where(fn($w)=>$w->where('s.last_name','like',$x)->orWhere('s.first_name','like',$x)->orWhere('s.middle_name','like',$x));}return view('admin.students.index',['students'=>$q->orderBy('s.last_name')->paginate(40)->withQueryString(),'groups'=>DB::table('study_groups')->where('active',1)->where('is_visible',1)->orderBy('name')->get()]);}
 public function create(){return view('admin.students.form',['student'=>null,'groups'=>$this->groups()]);}
 public function store(Request $r,CredentialService $c){$d=$this->validated($r);$credentials=null;DB::transaction(function()use($d,$c,&$credentials){$id=DB::table('students')->insertGetId($d+['created_at'=>now(),'updated_at'=>now()]);$this->membership($id,$d['current_group_id']);$credentials=$this->createAccount($id,$d['last_name'],$d['first_name'],$d['middle_name']??null,$c);});return redirect()->route('admin.students.index')->with('success','Студент добавлен. Учётная запись создана автоматически.')->with('created_credentials',$credentials);}
 public function edit($id){$s=DB::table('students')->find($id);abort_if(!$s,404);$account=User::where('student_id',$id)->first();$movements=DB::table('student_movements')->where('student_id',$id)->orderByDesc('effective_on')->orderByDesc('id')->get();
    $orders=DB::table('official_documents')->where('student_id',$id)->orderByDesc('created_at')->get();
    $private=DB::table('student_private_profiles')->where('student_id',$id)->first();
    $representatives=DB::table('student_representatives')->where('student_id',$id)->orderBy('id')->get();
    $social=DB::table('student_social_statuses as ss')->join('student_social_categories as sc','sc.id','=','ss.category_id')->where('ss.student_id',$id)->select('ss.*','sc.name as category_name')->orderByDesc('ss.valid_from')->get();
    $achievements=DB::table('student_achievements')->where('student_id',$id)->orderByDesc('achievement_date')->get();
    $grades=DB::table('grade_records')->where('student_id',$id)->selectRaw('count(*) as cnt, avg(value) as avg_grade')->first();
    $attendance=DB::table('attendance_records')->where('student_id',$id)->selectRaw("count(*) as total, sum(case when status in ('absent','excused','sick') then 1 else 0 end) as missed")->first();
    $semesterResults=DB::table('semester_results as r')->join('subjects as sub','sub.id','=','r.subject_id')->where('r.student_id',$id)->select('r.*','sub.name as subject_name')->orderByDesc('r.id')->limit(50)->get();
    $practice=DB::table('practice_placements')->where('student_id',$id)->orderByDesc('id')->get();
    $scholarships=DB::table('scholarship_decisions as d')->join('scholarship_commissions as sc','sc.id','=','d.scholarship_commission_id')->where('d.student_id',$id)->select('d.*','sc.protocol_number','sc.meeting_on')->orderByDesc('sc.meeting_on')->get();
    $dormitory=DB::table('dormitory_stays')->where('student_id',$id)->orderByDesc('id')->get();
    $library=DB::table('library_loans')->where('student_id',$id)->orderByDesc('id')->limit(30)->get();
    return view('admin.students.form',compact('account','movements','orders','private','representatives','social','achievements','grades','attendance','semesterResults','practice','scholarships','dormitory','library')+['student'=>$s,'groups'=>$this->groups()]);}
 public function update(Request $r,$id){abort_unless(DB::table('students')->where('id',$id)->exists(),404);$d=$this->validated($r);DB::table('students')->where('id',$id)->update($d+['updated_at'=>now()]);if($d['status']==='active')$this->membership($id,$d['current_group_id']);return back()->with('success','Карточка сохранена');}
 public function destroy($id){$s=DB::table('students')->find($id);abort_if(!$s,404);DB::transaction(function()use($id){DB::table('students')->where('id',$id)->update(['status'=>'expelled','left_on'=>date('Y-m-d'),'updated_at'=>now()]);DB::table('student_group_memberships')->where('student_id',$id)->where('status','active')->update(['status'=>'inactive','updated_at'=>now()]);});return redirect()->route('admin.students.index')->with('success','Студент переведён в архив (отчислен)');}
 public function bulk(Request $r){return view('admin.students.bulk',['groups'=>$this->groups(),'selectedGroup'=>$r->integer('group')?:null]);}
 public function bulkStore(Request $r,CredentialService $c){$d=$r->validate(['current_group_id'=>'required|exists:study_groups,id','students'=>'required|string','enrolled_on'=>'required|date','order_number'=>'required|string|max:100','order_date'=>'required|date','basis'=>'nullable|string|max:5000']);$p=$r->attributes->get('academic_period');abort_if(!$p,422,'Не выбран учебный период.');$lines=preg_split('/\\R/u',trim($d['students']));$created=0;$skipped=[];$credentials=[];DB::transaction(function()use($r,$lines,$d,$p,$c,&$created,&$skipped,&$credentials){$orderId=DB::table('academic_orders')->insertGetId(['academic_period_id'=>$p->id,'number'=>$d['order_number'],'order_date'=>$d['order_date'],'student_id'=>null,'type'=>'enrollment','title'=>'Зачисление студентов','basis'=>$d['basis']??null,'created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);foreach($lines as $n=>$line){$line=trim(preg_replace('/[;\\t]+/u',' ',trim($line)));if($line==='')continue;$parts=preg_split('/\\s+/u',$line,3);if(count($parts)<2){$skipped[]='Строка '.($n+1).': '.$line;continue;}[$last,$first]=$parts;$middle=$parts[2]??null;$exists=DB::table('students')->where('last_name',$last)->where('first_name',$first)->where('middle_name',$middle)->where('status','active')->exists();if($exists){$skipped[]='Дубликат: '.$line;continue;}$id=DB::table('students')->insertGetId(['current_group_id'=>$d['current_group_id'],'last_name'=>$last,'first_name'=>$first,'middle_name'=>$middle,'status'=>'active','enrolled_on'=>$d['enrolled_on'],'created_at'=>now(),'updated_at'=>now()]);DB::table('student_group_memberships')->insert(['student_id'=>$id,'academic_period_id'=>$p->id,'study_group_id'=>$d['current_group_id'],'starts_on'=>$d['enrolled_on'],'ends_on'=>null,'status'=>'active','created_at'=>now(),'updated_at'=>now()]);DB::table('student_movements')->insert(['student_id'=>$id,'academic_period_id'=>$p->id,'type'=>'enrollment','from_group_id'=>null,'to_group_id'=>$d['current_group_id'],'effective_on'=>$d['enrolled_on'],'academic_order_id'=>$orderId,'order_number'=>$d['order_number'],'order_date'=>$d['order_date'],'basis'=>$d['basis']??null,'created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);$credentials[]=$this->createAccount($id,$last,$first,$middle,$c);$created++;}});return redirect()->route('academic.movements')->with('success','Зачислено студентов: '.$created.'. Учётные записи созданы автоматически'.($skipped?' · пропущено: '.count($skipped):''))->with('bulk_skipped',$skipped)->with('created_credentials',$credentials);}
 public function bulkAction(Request $r){$d=$r->validate(['student_ids'=>'required|array|min:1','student_ids.*'=>'integer|exists:students,id','action'=>'required|in:transfer,academic_leave,expel,graduate','target_group_id'=>'nullable|exists:study_groups,id','order_number'=>'required|string|max:100','order_date'=>'required|date','effective_on'=>'required|date','basis'=>'nullable|string|max:5000']);if($d['action']==='transfer')abort_if(empty($d['target_group_id']),422,'Выберите группу назначения.');$p=$r->attributes->get('academic_period');abort_if(!$p,422,'Не выбран учебный период.');$type=['transfer'=>'transfer','academic_leave'=>'academic_leave','expel'=>'expulsion','graduate'=>'graduation'][$d['action']];$title=['transfer'=>'Массовый перевод студентов','academic_leave'=>'Академический отпуск','expel'=>'Отчисление студентов','graduate'=>'Выпуск студентов'][$d['action']];DB::transaction(function()use($r,$d,$p,$type,$title){$orderId=DB::table('academic_orders')->insertGetId(['academic_period_id'=>$p->id,'number'=>$d['order_number'],'order_date'=>$d['order_date'],'student_id'=>null,'type'=>$type,'title'=>$title,'basis'=>$d['basis']??null,'created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);foreach($d['student_ids'] as $id){$s=DB::table('students')->find($id);if(!$s)continue;$to=$d['action']==='transfer'?$d['target_group_id']:null;DB::table('student_movements')->insert(['student_id'=>$id,'academic_period_id'=>$p->id,'type'=>$type,'from_group_id'=>$s->current_group_id,'to_group_id'=>$to,'effective_on'=>$d['effective_on'],'academic_order_id'=>$orderId,'order_number'=>$d['order_number'],'order_date'=>$d['order_date'],'basis'=>$d['basis']??null,'created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);if($d['action']==='transfer'){DB::table('student_group_memberships')->where('student_id',$id)->where('status','active')->update(['status'=>'inactive','ends_on'=>$d['effective_on'],'updated_at'=>now()]);DB::table('students')->where('id',$id)->update(['current_group_id'=>$to,'status'=>'active','left_on'=>null,'updated_at'=>now()]);DB::table('student_group_memberships')->insert(['student_id'=>$id,'academic_period_id'=>$p->id,'study_group_id'=>$to,'starts_on'=>$d['effective_on'],'ends_on'=>null,'status'=>'active','created_at'=>now(),'updated_at'=>now()]);}else{$status=['academic_leave'=>'academic_leave','expel'=>'expelled','graduate'=>'graduated'][$d['action']];$up=['status'=>$status,'updated_at'=>now()];if(in_array($status,['expelled','graduated']))$up['left_on']=$d['effective_on'];DB::table('students')->where('id',$id)->update($up);DB::table('student_group_memberships')->where('student_id',$id)->where('status','active')->update(['status'=>'inactive','ends_on'=>$d['effective_on'],'updated_at'=>now()]);}}});return redirect()->route('academic.movements')->with('success','Приказ зарегистрирован, движение студентов записано в историю');}
 private function createAccount(int $studentId,string $last,string $first,?string $middle,CredentialService $c):array{$role=Role::where('code','student')->firstOrFail();$plain=$c->password();$login=$c->login($last,$first,$studentId);$u=User::create($c->pack($plain)+['name'=>trim($last.' '.$first.' '.$middle),'login'=>$login,'email'=>$login.'@students.local','student_id'=>$studentId,'is_active'=>true]);$u->roles()->syncWithoutDetaching([$role->id]);return ['name'=>$u->name,'login'=>$login,'password'=>$plain,'type'=>'Студент'];}
 private function groups(){return DB::table('study_groups')->where('active',1)->orderBy('name')->get();}
 private function validated(Request $r){return $r->validate(['current_group_id'=>'required|exists:study_groups,id','last_name'=>'required|max:100','first_name'=>'required|max:100','middle_name'=>'nullable|max:100','status'=>'required|in:active,academic_leave,expelled,graduated,transferred','enrolled_on'=>'nullable|date','left_on'=>'nullable|date']);}
 private function membership($studentId,$groupId){$period=DB::table('academic_periods')->where('is_current',1)->first()?:DB::table('academic_periods')->orderByDesc('starts_on')->first();if($period)DB::table('student_group_memberships')->updateOrInsert(['student_id'=>$studentId,'academic_period_id'=>$period->id],['study_group_id'=>$groupId,'status'=>'active','updated_at'=>now(),'created_at'=>now()]);}
}
